from collections import defaultdict

def calculate_substrings(s):
    n = len(s)
    prefix = [0] * (n + 1)
    chars = {}

    # Dictionary to store counts of distinct characters
    for i in range(1, n + 1):
        prefix[i] = prefix[i - 1]
        chars[s[i - 1]] = chars.get(s[i - 1], 0) + 1

    # Sort the string by character code
    s_sorted = sorted(s)

    # Number of characters
    k = set(chars.values())

    def is_rotation_s(s, k_char):
        n = len(s)
        s_char_count = {}

        # Count characters in s considering rotations
        for i in range(n):
            s_char_count[s[i]] = s_char_count.get(s[i], 0) + 1
            for j in range(i + 1, n):
                s_char_count[s[(i + j) % n]] = s_char_count.get(s[(i + j) % n], 0) + 1

        return s_char_count == k_char

    sub_count = 0

    # Iterate through all unique characters and check rotations
    for k_char in k:
        actual_count = k_char * (n // len(k_char))
        if is_rotation_s(s_sorted, k_char):
            sub_count += actual_count

        for i in range(1, len(s)):
            new_s = s_sorted[:i] + ['*'] + s_sorted[i:]
            if all(x in chars for x in set(new_s)):
                sub_count += prefix[i] - (prefix[i - actual_count] if i >= actual_count else 0)

    if len(s) % len(k_char) > 0:
        count = n // len(k_char) + 1
    else:
        count = n // len(k_char)

    return count * sub_count

