def calculate_situations(n, prices):
    gcd_prices = defaultdict(int)
    for price in prices:
        gcd_products = set()
        current_gcd = 0
        for i in range(1, min(100, price) + 1):
            if price % i == 0:
                try:
                    current_gcd = gcd(current_gcd, i)
                    gcd_products.add(i)
                except ValueError:  # Handle the case where gcd is 1
                    current_gcd = i
        gcd_prices[gcd(current_gcd, price)] = gcd_products

    result = 0
    for gcd, gcd_grp in sorted(gcd_prices.items()):
        for group in sorted(gcd_grp):
            result = (result + (2 ** len(gcd_grp) - len(gcd_grp) + 1) * len(gcd_grp)) % (10**9 + 7)
