    # Check if one set of columns covers another
    def is_covering(columns, covering_columns):
        for point in columns:
            if not any(point in covering_columns for point in columns):
                return False
        return True

    # Sort points for merging
    sorted_points = sorted(sum(points_set, tuple()))
    sorted_points = set(sorted_points)

