from collections import defaultdict

def visit_museums():
    n, m, d = map(int, input().split())
    cities = [[] for _ in range(n)]
    for _ in range(m):
        u, v = map(int, input().split())
        cities[u-1].append(v-1)
    museums = ["1"] + [input() for _ in range(n)]

    # Create adjacency list for museums to cities
    museum_to_city = defaultdict(set)
    for city in range(n):
        for museum_day in museums[city+1]:
            if museum_day == '1':
                museum_to_city[museum_day].add(city)

    # DFS to find maximum number of distinct museums
    def dfs(city):
        visited = set()
        queue = [(city, 0)]
        max_distinct_museums = 1
        museum_count = {museum: 0 for museum in museum_to_city[1]}

        while queue:
            current_city, dist = queue.pop(0)
            visited.add(current_city)
            distinct_museums = museum_count[current_city]

            for next_city in museum_to_city[current_city]:
                if next_city not in visited and current_city not in visited:
                    museum_count[next_city] = distinct_museums + 1
                    queue.append((next_city, dist + 1))
                    max_distinct_museums = max(max_distinct_museums, museum_count[next_city])

        return max_distinct_museums

    return max(dfs(city) for city in range(n))

