from math import gcd

def hash_function(x):
    # If x is not divisible by k, returns x itself, otherwise recursively divides and updates the result
    if x % gcd(x, k) == 0:
        return k - hash_function(x // k)
    else:
        return x

def hashExpression(a, b):
    # Returns the hash of the expression (a + b) mod k
    return hash_function(a + b) % k

def solve(n, k, numbers):
    if n == 1:
        if numbers[0] == 1:
            return "YES\n" + str(numbers[0])
        else:
            return "NO"

    min_result = float('inf')
    for i in range(n):
        for j in range(n):
            if i != j and set([num for num in numbers if num <= i]) <= set([num for num in numbers if num <= j]):
                # Check if we can make the remaining numbers lead to a 1 through the hash function
                remainder = hashExpression(i, j)
                if remainder is None or (numbers[i] - remainder) % k == 0:
                    if remainder == 1:
                        min_result = min(min_result, set([i, j]))
                        break
    if min_result == float('inf'):
        return "NO"

    results = []
    while min_result:
        if min_result % k == 1:
            break
        i, j = min_result, hash_expression(min_result)
        results.append([i, j])
        min_result = max(0, min_result - 1)
        set_numbers = set(numbers)
        set_numbers.remove(i)
        set_numbers.remove(j)
        set_options = [num for num in numbers if num <= min_result]
        if i in set_options:
            set_options.remove(i)
        if j in set_options:
            set_options.remove(j)
        return i, j

