from typing import List

def read_input() -> tuple:
    n, m = map(int, input().split())
    teams = list(map(int, input().split()))
    pairs = []
    for _ in range(m):
        u, v = map(int, input().split())
        if u != v:
            pairs.append(u - 1)
    return n, m, teams, pairs

def build_matrix(results: List[List[int]]) -> List[List[int]]:
    matrix = []
    for _ in range(len(results)):
        matrix.append([0] * len(results))
    for i, winning_team in enumerate(results):
        matrix[i][winning_team - 1] = 1
    return matrix

def check_beautiful(matrix: List[List[int]]) -> int:
    n = len(matrix)
    beautiful_count = 0
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if matrix[i][j] + matrix[j][k] + matrix[k][i] == 1:
                    beautiful_count += 1
    return beautiful_count

def compute_best_beauty(results: List[List[int]], remaining_pairs: List[int]):
    # If there are no remaining matches, the maximum beauty is the number of beautiful triples in the results
    if not remaining_pairs:
        return sum(results[i][j] != 0 for i, j in itertools.permutations(list(range(len(results))), 2))

    # Calculate the number of beautiful triples if all remaining matches were to be played
    triple_count = sum(results[i][j] + results[j][k] + results[k][i] == 1 for i, j, k in itertools.permutations(remaining_pairs, 3))

    # Try increasing the beauty of the league by playing any one of the remaining matches
    best_beauty = triple_count
    max_beauty_matrix = None
    for i, remaining_winning_team in enumerate(remaining_pairs):
        for middle_winning_team in remaining_pairs:
            if i != middle_winning_team:
                new_results = results.copy()
                new_results[i][remaining_winning_team - 1] = 1
                new_results[remaining_winning_team - 1][i] = 0
                new_results[i][middle_winning_team - 1] = 1
                new_results[middle_winning_team - 1][i] = 1
                new_matrix = build_matrix(new_results)
                total_beauty = check_beautiful(new_matrix)
                if total_beauty > best_beauty:
                    best_beauty = total_beauty
                    max_beauty_matrix = new_matrix

    return best_beauty, max_beauty_matrix

def print_results_beauty(results: List[List[int]], best_beauty: int, matrix: List[List[int]]):
    print(' '.join('0' if result == 0 else '1' for _ in range(len(results))))
    for i in range(1, len(results) + 1):
        print(' '.join(str(int(0 in matrix[i-1][j-1] for j in range(len(matrix[i-1])))) for _ in range(len(results))))
        print()

def main():
    n, m, teams, pairs = read_input()
    results = build_matrix(teams)

    remaining_matches = set(range(m)) - set(pairs)
    best_beauty, max_beauty_matrix = compute_best_beauty(results, list(remaining_matches))

    print_results_beauty(results, best_beauty, max_beauty_matrix)

if __name__ == "__main__":
    main()
