        balance_side = 0
        for i in range(n):
            if len(stack) >= 2 and (stack[-1] - stack[-2]) * balance_side > 0:
                stack.pop()
            weight_i, side_i = A[perm[i]], S[perm[i]]
            if side_i == 'L':
                if balance_side > 0:
