                else:
                    stack += list(weights - set((x * balance_side * (-1 for _ in range(-side_i if side_i == 'R' else 1)) if side_i == 'L' else 0) for x in stack))
            else:
                if balance_side < 0:
                    stack = sorted(stack, key=lambda x: x * balance_side)[-1::-1]
