def is_valid_tree(edges):
    from heapq import heapify, heappop, heappush
    from collections import defaultdict

    # Convert all edge indices to digits
    edges = [f"{int(e[0][:-1])}" for e in edges] + [f"{int(e[1][:-1])}" for e in edges]

    # Build adjacency list
    graph = defaultdict(list)
    for e in edges:
        graph[e[0]].append(e[1])
        graph[e[1]].append(e[0])

    # Topological sort
    order = []
    in_degree = defaultdict(int)
    for vertex in graph:
        for neighbor in graph[vertex]:
            in_degree[neighbor] += 1
    queue = [vertex for vertex in graph if in_degree[vertex] == 0]
    while queue:
        vertex = queue.pop(0)
        order.append(vertex)
        for neighbor in graph[vertex]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)
    # Check if we formed a tree
    if len(order) != len(graph):
        return False

    # Find any cycle in the partial topological order
    def detect_cycle(u):
        visited = set([u])
        stack = [u]

        while stack:
            vertex = stack.pop()
            for neighbor in graph[vertex]:
                if neighbor in visited:
                    return neighbor
                elif neighbor not in visited:
                    stack.append(neighbor)
                    visited.add(neighbor)
        return None

    cycle = detect_cycle(order[-1])
    if cycle:
        return False

    def build_tree(order, parent, edge_set):
        if len(order) == 1:
            return [(order[0], parent)]
        else:
            children = set(parent)
            for neighbor in graph[order[-1]]:
                if neighbor not in children:
                    children.add(neighbor)
            children = list(children)
            l = children[0]
            r = None
            for c in children[1:]:
                if not graph[l][len(graph[l])-1] == c:
                    r = c
            if r:
                return [(order[-1], parent), (order[0], r), (parent, order[-1])]
            else:
                return [(order[-1], parent), (parent, order[-1])]
    return build_tree(order, order[-1], edge_set)

