def build_graph(respect_levels):
    num_parrots = len(respect_levels)
    graph = defaultdict(list)

    for i in range(num_parrots):
        for j in range(i + 1, num_parrots):
            if respect_levels[i] == respect_levels[j % num_parrots]:
                graph[i].append(j)
                graph[j].append(i)

    return graph

def get_chattering_time(parrot, respect_levels):
    num_seconds = 0
    visited = set()
    queue = [(parrot, num_seconds)]

    while queue:
        parrot, num_seconds = queue.pop(0)
        if parrot in visited:
            visited.clear()
        visited.add(parrot)

        for neighbor in graph[parrot]:
            if neighbor not in visited:
                target_seconds = max(num_seconds + 1, get_chattering_time(neighbor, respect_levels))
                queue.append((neighbor, target_seconds))
                if num_seconds + 1 == target_seconds: # arrived within one time step from this node
                    return target_seconds

    return num_seconds

