from typing import List, Tuple

def smallest_state_partition(edges: List[Tuple[int, int]]) -> List[int]:
    """Partition the graph into states for cities such that each city has an even number of "inner" roads."""

    def check_states(num_states: int) -> bool:
        """Check if it's possible to partition the cities into 'num_states' such that each city has an even number of "inner" roads."""

        @lru_cache(maxsize=None)
        def dfs(node: int, previous_state: int, has_odd_inners: bool) -> int:
            """Depth-first search to determine if a partition is reachable."""

            if node == -1:
                return 1

            current_odd_inner = 0
            sum_odd_inners = 0
            odd_states = 0

            for neighbor in graph[node]:
                if neighbor != previous_state:
                    odd_states += dfs(neighbor, node, True)

            if has_odd_inners:
                current_odd_inner = odd_states % 2
                sum_odd_inners = odd_states
            else:
                sum_odd_inners += odd_states

            return (current_odd_inner + sum_odd_inners) % num_states != 0

        # Check all possible partitions from 2 to num_states
        for num in range(2, num_states + 1):
            if dfs(nodes[-1], -1, any(e[1] == x and e[0] == next_num for num, next_num in next_nodes_map[num])):
                return num

        return None

    nodes, graph, next_nodes_map = [], [], {}
    for x, y in edges:
        nodes.extend([x, y])

    nodes_set = set(nodes)
    x = next(iter(nodes_set))
    init_states = [int(x % 2) for _ in nodes]

    x_next_nodes = {}
    y_next_nodes = {}

    for x in nodes_set - {x}:
        y = next(iter(next_nodes_map[x + 1]))
        cars = [None, *next_nodes_map[x]]
        while y not in x_next_nodes and cars:
            if cars[-1] == next_nodes_map[x][cars[0]]:
                x_next_nodes[cars[0]] = cars.pop()
            else:
                next_nodes_map[x][cars[0]] = cars.pop()

    for x in nodes - {x}:
        y = next(iter(next_nodes_map[x + 1]))
        cars = [None, *next_nodes_map[x]]
        while y not in y_next_nodes and cars:
            if cars[-1] == next_nodes_map[x][cars[0]]:
                y_next_nodes[cars[0]] = cars.pop()
            else:
                next_nodes_map[x][cars[0]] = cars.pop()

    next_nodes_map[x] = [y_next_nodes.pop(y), x_next_nodes.pop(x)]

    num_states_ok = 2
    while True:
        num_states = smallest_state_partition(edges)
        if num_states is None:
            break
        num_states_ok += 1
    return num_states_ok

