def find_matches(tree):
    count = {j: i for i, j in tree}

    for i in range(1, len(tree)):
        if count[tree[i][0]] > count[tree[0][0]]:
            break
        if count[i] in tree[count[tree[i][0]]][1:]:
            return 0

    count.pop(tree[0][0], 0)

    return count

